var g={blocks:"blocked_by",relates:"relates",duplicates:"duplicated_by"};async function c(r,e,t,i,s){return(await r.list("relations",{filter:{project:e,issue:t,target:i,kind:s},limit:200})).items}var m=async({project:r,issue:e,target:t,kind:i,remove:s},{data:n})=>{if(e===t)throw Error("An issue cannot relate to itself.");let o=g[i],[l,a]=await Promise.all([c(n,r,e,t,i),c(n,r,t,e,o)]);if(s)return await Promise.all([...l,...a].map((d)=>n.remove("relations",d.id))),{removed:l.length+a.length};if(l.length===0)await n.create("relations",{project:r,issue:e,target:t,kind:i});if(a.length===0)await n.create("relations",{project:r,issue:t,target:e,kind:o});return{related:!0}},f=m;export{f as default};
